// `createIdGenerator` as `@solid-primitives/utils@7.0.0-next.4` declares it
// (`dist/index.d.ts`); `createIdGeneratorOpen` is its control, with `returns`
// left open in the contract. `createCounter` returns a signal's accessor, as
// `const [count] = createSignal(0); return count;` is typed by `solid-js`.
//
// The signatures are `tsc`-clean for every call `App.tsx` makes, so nothing
// here duplicates a type diagnostic.
export declare const createIdGenerator: () => () => string;
export declare const createIdGeneratorOpen: () => () => string;
export declare function createCounter(): () => number;
